function markDirty() {
  var dirty = edits.size > 0;
  root.setAttribute('data-dirty', dirty ? 'true' : 'false');
  if (save) save.disabled = !dirty || root.querySelector('[data-invalid="true"]') !== null;
  if (discard) discard.disabled = !dirty;
  if (status) status.textContent = dirty ? root.getAttribute('data-copy-restart') || '' : '';

root.querySelectorAll('[data-config-path]').forEach(function (control) {
  control.addEventListener('change', function () {
    var field = control.closest('.delendai-config__field');
    try {
      var path = JSON.parse(control.getAttribute('data-config-path'));
      var kind = control.getAttribute('data-config-kind');
      var remove = control.getAttribute('data-config-optional') === 'true' && kind !== 'boolean' && control.value === '';
      if (remove) edits.set(JSON.stringify(path), { action: 'delete', path: path });
      else edits.set(JSON.stringify(path), { action: 'set', path: path, value: valueOf(control, kind) });
      if (field) field.setAttribute('data-invalid', 'false');
    } catch (_) {
      if (field) field.setAttribute('data-invalid', 'true');
    }
    markDirty();

if (save) save.addEventListener('click', function () {
  if (save.disabled) return;
  save.disabled = true;
  root.setAttribute('data-state', 'saving');
  post({ command: 'saveConfiguration', expectedDigest: initialDigest, edits: Array.from(edits.values()) });
});
if (discard) discard.addEventListener('click', function () {
  post({ command: 'discardConfiguration' });
});

window.addEventListener('message', function (event) {
  var message = event.data || {};
  if (message.command === 'configurationSaved') {
    edits.clear();
    initialDigest = typeof message.digest === 'string' ? message.digest : initialDigest;
    root.setAttribute('data-config-digest', initialDigest);
    root.setAttribute('data-state', 'ready');
    markDirty();

await panel.webview.postMessage?.({
	command: 'configurationSaved',
	digest: result.document.digest,
});
return result.changed;

const html = withCsp(
	'configuration-center',
	injectBridge(
		renderConfigurationCenter({
			model,
			lang,
			...(pluginId === undefined ? {} : { pluginId }),
		}),
	),
);
const panel = deps.vscode.window.createWebviewPanel(
	'delendaiPluginConfig',
	pluginId === undefined
		? strings.panelTitle
		: `${strings.panelTitle} — ${pluginId}`,
	deps.vscode.ViewColumn.One,
	{ enableScripts: true },
);
panel.webview.html = html;
panel.webview.onDidReceiveMessage?.((raw: unknown) => {

panel.webview.onDidReceiveMessage?.(async (raw: unknown) => {
	const parsed =
		CONFIGURATION_CENTER_MESSAGE_SCHEMA.safeParse(raw);
	if (!parsed.success) return;
	if (parsed.data.command === 'discardConfiguration') {
		panel.webview.html = html;
		return;
	}
	// This panel used to drop `saveConfiguration`: the webview
	// disabled Save, posted the edits, and nothing answered.
	try {
		await saveAndAnswer(panel, workspaceRoot, parsed.data);
	} catch (err) {

if (
	parsed.data.command === 'discardConfiguration'
) {
	const html = await renderPanel(
		deps,
		workspaceRoot,
		lang,
		strings,
	);
	if (!disposed) panel.webview.html = html;
	return;

const providerId = await pickProviderId(deps);
if (providerId === undefined || providerId.length === 0) return;
const reason = await deps.vscode.window.showInputBox?.({
	prompt: stringsFor(deps).reasonPrompt,
});
await deps.client.request(
	formatToolName(
		deps.namespacePrefix,
		'orchestrator-runner_set_provider_state',
	),
	{
		providerId,
		state,
		...(reason === undefined || reason.length === 0 ? {} : { reason }),
	},
);

export const registerProvidersPauseCommand = (deps: IProviderActionsDeps) =>
	deps.vscode.commands.registerCommand(PROVIDERS_PAUSE_COMMAND, async () => {
		try {
			await setProviderState(deps, 'rate-limited', (s) => s.pausedInfo);
		} catch (err) {
			await showCommandError(deps.vscode, 'pause provider', err);
		}
	});

export const registerProvidersResumeCommand = (deps: IProviderActionsDeps) =>
	deps.vscode.commands.registerCommand(PROVIDERS_RESUME_COMMAND, async () => {
		try {
			await setProviderState(deps, 'available', (s) => s.resumedInfo);
		} catch (err) {
			await showCommandError(deps.vscode, 'resume provider', err);
